\begin{tikzpicture}[x=1cm,y=1cm,line cap=round,line join=round,font=\sffamily\small]
% plane mirror
\draw[line width=1.2pt] (0,-0.2) -- (0,3.4);
\foreach \y in {0.0,0.35,...,3.3} {\draw[line width=0.45pt] (0,\y) -- (0.22,\y-0.16);}
\node[above] at (0,3.45) {plane mirror};
% object (Navya) left of mirror — left arm raised
\draw[line width=0.9pt] (-2.4,0.2) -- (-2.4,1.6);
\fill (-2.4,1.85) circle (0.18);
\draw[line width=0.9pt] (-2.4,1.45) -- (-1.7,1.45);
\draw[line width=0.9pt] (-2.4,1.45) -- (-3.1,2.35);
\node[font=\footnotesize] at (-3.15,2.55) {L};
\node[below] at (-2.4,0.05) {object};
\node[font=\footnotesize] at (-2.4,-0.35) {left arm up};
% image (dashed) right of mirror — appears right arm raised
\draw[line width=0.9pt,dashed] (2.4,0.2) -- (2.4,1.6);
\draw[dashed,fill=white] (2.4,1.85) circle (0.18);
\draw[line width=0.9pt,dashed] (2.4,1.45) -- (1.7,1.45);
\draw[line width=0.9pt,dashed] (2.4,1.45) -- (3.1,2.35);
\node[font=\footnotesize] at (3.15,2.55) {R};
\node[below] at (2.4,0.05) {image};
\node[font=\footnotesize] at (2.4,-0.35) {appears right};
\end{tikzpicture}
